
// LuminoAI Autonomous Cleanroom Protection Shield
(function() {
    'use strict';
    // 1. Disable Context Menu
    document.addEventListener('contextmenu', function(e) {
        e.preventDefault();
        return false;
    }, { capture: true });

    // 2. Block Inspection Keyboard Shortcuts
    document.addEventListener('keydown', function(e) {
        // F12
        if (e.keyCode === 123) { e.preventDefault(); e.stopPropagation(); return false; }
        // Ctrl+Shift+I / J / C (Windows/Linux)
        if (e.ctrlKey && e.shiftKey && (e.keyCode === 73 || e.keyCode === 74 || e.keyCode === 67)) {
            e.preventDefault(); e.stopPropagation(); return false;
        }
        // Cmd+Alt+I / J / C / U (Mac)
        if (e.metaKey && e.altKey && (e.keyCode === 73 || e.keyCode === 74 || e.keyCode === 67 || e.keyCode === 85)) {
            e.preventDefault(); e.stopPropagation(); return false;
        }
        // Ctrl+U (View Source)
        if (e.ctrlKey && e.keyCode === 85) { e.preventDefault(); e.stopPropagation(); return false; }
        // Ctrl+S (Save Page)
        if ((e.ctrlKey || e.metaKey) && e.keyCode === 83) { e.preventDefault(); e.stopPropagation(); return false; }
    }, { capture: true });

    // 3. Console Nullifier
    try {
        var _noop = function() {};
        window.console.log = _noop;
        window.console.warn = _noop;
        window.console.error = _noop;
        window.console.info = _noop;
        window.console.debug = _noop;
    } catch(err) {}

    // 4. Debugger Trap Loop
    function _trap() {
        try {
            (function() {
                return false;
            }['constructor']('debugger')['call']());
        } catch(e) {}
    }
    setInterval(_trap, 1000);
})();
